    lengthIn: {"value":154.1,"source":{"kind":"reference","name":"Autoblog","url":"https://www.autoblog.com/buy/2024-Mazda-MX_5+Miata-Club__2dr_Convertible/specs/","asOf":"2026-11-24","note":"Search summary: 'Autoblog's Club listing also gives a 154.1-inch length' (2024 MX-5 Miata Club 2dr Convertible). No second source and no Mazda 2024 figure was seen. Read from search-result summary; page not opened."}},
